24	/**
25	 * Traceability sensor for {@code docs/requirements.md}.
26	 *
27	 * <p>Every use case names the requirements it realizes in a
28	 * {@code **Requirements:**} line of its Overview, and the catalogue mirrors that
29	 * in a <em>Use Cases</em> column, so the trace can be read from either end. Two
30	 * copies of the same link drift as soon as one of them is edited alone, and a
31	 * requirement nobody realizes is invisible until someone looks for it. This
32	 * sensor closes the first arrow of {@code Requirement → Use Case → … → Test},
33	 * the way {@link BusinessRuleTraceabilityTest} and
34	 * {@link UseCaseTraceabilityTest} close the ones after it.
35	 *
36	 * <p>What it checks:
37	 *
38	 * <ul>
39	 *   <li><strong>Referential integrity</strong> — every id a use case lists is a
40	 *       row of the catalogue, and every use case the catalogue lists exists.</li>
41	 *   <li><strong>Both directions agree</strong> — the <em>Use Cases</em> cell of
42	 *       a requirement names exactly the use cases whose
43	 *       {@code **Requirements:**} line lists it.</li>
44	 *   <li><strong>Every functional requirement is realized</strong> by at least
45	 *       one use case, and every use case realizes at least one functional
46	 *       requirement. Non-functional requirements and constraints may stand
47	 *       without one: they shape how the system is built, not what a user does.</li>
48	 *   <li><strong>Shared rules carry their origin along</strong> — the
49	 *       requirements a {@code GR-NNN} comes from are listed by the use cases
50	 *       applying it, so the chain through {@code docs/business_rules.md} does
51	 *       not skip a link.</li>
52	 *   <li><strong>The status follows the use cases</strong> — a requirement is
53	 *       <em>Verified</em> exactly when every use case realizing it is
54	 *       <em>Done</em> or <em>Tested</em>; the same derivation
55	 *       {@code /spec-review} applies.</li>
56	 * </ul>
57	 *
58	 * <p>Failures list every violation at once rather than stopping at the first,
59	 * so the report reads as a work list.
60	 */
61	@Tag("sensor")
62	class RequirementTraceabilityTest {
63	
64	    private static final Path DOCS_DIR = Path.of("docs");
65	    private static final Path CATALOGUE = DOCS_DIR.resolve("requirements.md");
66	    private static final Path BUSINESS_RULES = DOCS_DIR.resolve("business_rules.md");
67	    private static final Path USE_CASE_DIR = DOCS_DIR.resolve("use_cases");
68	
69	    /** {@code | FR-001 | Welcome Page | As a visitor, … | UC-001 | High | Verified |} */
70	    private static final Pattern CATALOGUE_ROW =
71	            Pattern.compile("^\\|[ \t]*((?:FR|NFR|C)-\\d{3})[ \t]*\\|(.*)\\|[ \t]*$", Pattern.MULTILINE);
