@@ -0,0 +1,109 @@
+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.PetClinicTestBase;
+import ai.unifiedprocess.petclinic.UseCase;
+import ai.unifiedprocess.petclinic.vet.domain.VetRepository;
+import com.vaadin.flow.component.grid.Grid;
+import org.jooq.DSLContext;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+
+import java.util.Map;
+import java.util.Set;
+import java.util.stream.IntStream;
+
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VETS;
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VET_SPECIALTIES;
+import static java.util.stream.Collectors.toMap;
+import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+
+/**
+ * UC-002: View Veterinarians.
+ */
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    /** The six veterinarians of the V2 seed data. */
+    private static final int VET_COUNT = 6;
+
+    @Autowired
+    private DSLContext dsl;
+
+    @Autowired
+    private VetRepository repository;
+
+    @Test
+    @UseCase(id = "UC-002")
+    void vetsGridListsEveryVeterinarianByFirstAndLastName() {
+        navigate(VeterinariansView.class);
+
+        assertDoesNotThrow(() -> find(Grid.class).single(), "Expected exactly one veterinarians grid");
+        assertEquals(VET_COUNT, test(find(Grid.class).single()).size(), "Expected a row for every veterinarian");
+        assertEquals(Set.of("James Carter", "Helen Leary", "Linda Douglas",
+                        "Rafael Ortega", "Henry Stevens", "Sharon Jenkins"),
+                specialtiesByVetName().keySet(),
+                "Expected every veterinarian's first and last name in the grid");
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void eachVetShowsTheSpecialtiesTheyHoldOrNone() {
+        navigate(VeterinariansView.class);
+
+        Map<String, String> specialties = specialtiesByVetName();
+        assertEquals("none", specialties.get("James Carter"), "Expected 'none' for a vet without specialties");
+        assertEquals("radiology", specialties.get("Helen Leary"), "Expected the one specialty of Helen Leary");
+        assertEquals("surgery", specialties.get("Rafael Ortega"), "Expected the one specialty of Rafael Ortega");
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-002")
+    void aVetsSpecialtiesAreListedAlphabetically() {
+        navigate(VeterinariansView.class);
+
+        // Linda Douglas was assigned surgery before dentistry, so only sorting by name gives this order.
+        assertEquals("dentistry, surgery", specialtiesByVetName().get("Linda Douglas"),
+                "Expected Linda Douglas's specialties alphabetically, comma-separated");
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void noVeterinariansRegisteredRendersAnEmptyGrid() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+
+        navigate(VeterinariansView.class);
+
+        assertDoesNotThrow(() -> find(Grid.class).single(), "Expected the veterinarians grid to render");
+        assertEquals(0, test(find(Grid.class).single()).size(), "Expected the grid to have no rows");
+    }
+
+    /**
+     * Scrolling happens in the browser and is not exercised here. This pins the
+     * backend side the grid relies on: each request asks for one window, and the
+     * windows cover every veterinarian exactly once.
+     */
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void vetsAreFetchedInWindowsOfTheRequestedSize() {
+        assertEquals(VET_COUNT, repository.count(), "Expected the total count for the grid's scrollbar");
+        assertEquals(2, repository.findPage(0, 2).count(), "Expected a first window of two veterinarians");
+        assertEquals(1, repository.findPage(5, 2).count(), "Expected the last window to hold the remaining vet");
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-003")
+    void veterinariansAreViewableWithoutLogin() {
+        // No authentication is performed, covering BR-003 (Anonymous Access).
+        assertDoesNotThrow(() -> navigate(VeterinariansView.class),
+                "Expected /vets to resolve to VeterinariansView without any login");
+    }
+
+    /** The specialties text of every grid row, keyed by "First Last". */
+    private Map<String, String> specialtiesByVetName() {
+        var grid = test(find(Grid.class).single());
+        return IntStream.range(0, grid.size()).boxed()
+                .collect(toMap(row -> grid.getCellText(row, 0) + " " + grid.getCellText(row, 1),
+                        row -> grid.getCellText(row, 2)));
+    }
+}
